// Compiles the browser code of the template pages (src/lib/templateSite/*Client.ts) into plain
// JavaScript text, saved in clientScripts.generated.ts. The pages ship exactly this text, so what
// the browser runs never depends on how the server code was compiled. Run it after editing a
// *Client.ts file: `npm run build:site-scripts`. A test fails when the generated file is stale.
import { readFileSync, writeFileSync } from "node:fs";
import { transformSync } from "esbuild";

const dir = new URL("../src/lib/templateSite/", import.meta.url);
const sources = { SHOWROOM_CLIENT_SOURCE: "showroomClient.ts", STORY_CLIENT_SOURCE: "storyClient.ts" };

export function compileClient(file) {
  const ts = readFileSync(new URL(file, dir), "utf8");
  const out = transformSync(ts, { loader: "ts", target: "es2019", format: "esm" }).code;
  return out.replace(/^export function /m, "function ").replace(/\nexport \{[^}]*\};?\s*$/, "").trim();
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const body = Object.entries(sources)
    .map(([name, file]) => `export const ${name} = ${JSON.stringify(compileClient(file))};\n`)
    .join("\n");
  writeFileSync(new URL("clientScripts.generated.ts", dir), `// Generated by scripts/build-site-scripts.mjs from the *Client.ts files. Do not edit by hand.\n\n${body}`);
  console.log("clientScripts.generated.ts written");
}
